const ACCESS_CODES = ['ali'];
const raw = $input.first().json || {};
const b = raw.body || raw;
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const bad = (msg, code) => [{ json: { valid: false, status_code: code || 400, error: msg } }];
if (Array.isArray(b) || typeof b !== 'object') return bad('Invalid request.');
if (!ACCESS_CODES.includes(s(b.access_code))) return bad('Invalid access code.', 401);
for (const k of ['lead_id', 'run_id', 'business_name', 'number']) {
  const v = b[k];
  if (v !== undefined && v !== null && typeof v === 'object') return bad('Only one lead per status request is allowed.');
}
const runId = s(b.run_id);
if (runId && !/^[A-Za-z0-9]{10,40}$/.test(runId)) return bad('Run id is not valid.');
const leadId = s(b.lead_id);
if (!/^[A-Za-z0-9_-]{3,64}$/.test(leadId)) return bad('Lead id is not valid.');
return [{ json: { valid: true, run_id: runId, lead_id: leadId, business_name: s(b.business_name).slice(0, 120), number: s(b.number).replace(/\D/g, '').slice(0, 15) } }];

const p = $('Parse WA Status').first().json;
const items = $input.all().map(i => i.json || {});
const R = (o) => [{ json: { response: o } }];
if (items.length && items[0].error) return R({ ok: false, error: 'Could not read the status from Google Sheets: ' + String(items[0].error.message || items[0].error).slice(0, 200) });
const rows = items.filter(r => r && String(r.Lead_ID || '') === p.lead_id);
if (!rows.length) return R({ ok: true, state: 'none', status: 'Not sent', run_id: '', message: 'No WhatsApp message has been recorded for this lead.' });
const stOf = (x) => String(x.Status || '').trim();
const LIVE = ['Sent', 'Delivered', 'Read', 'Played'];
const row = (p.run_id && rows.find(r => String(r.Run_ID || '') === p.run_id)) || rows.find(r => LIVE.includes(stOf(r))) || rows[0];
const st = stOf(row);
const rid = String(row.Run_ID || '').trim();
const err = String(row.Error || '').slice(0, 200);
const t = Date.parse(String(row.Updated_At || row.Saved_At || ''));
const waited = Number.isFinite(t) ? Math.floor((Date.now() - t) / 1000) : 0;
const base = { ok: true, run_id: rid, number: String(row.WhatsApp_Number || '').replace(/\D/g, ''), business_name: String(row.Business_Name || ''), updated_at: String(row.Updated_At || '') };
const out = (state, status, message) => R(Object.assign({}, base, { state: state, status: status, message: message }));
if (st === 'Sent') return out('sent', 'Sent', 'Sent - accepted by WhatsApp (waiting for delivery confirmation).');
if (st === 'Delivered') return out('sent', 'Delivered', 'Delivered to the recipient\'s phone.');
if (st === 'Read') return out('sent', 'Read', 'Delivered and read by the recipient.');
if (st === 'Played') return out('sent', 'Played', 'Delivered and played by the recipient.');
if (st === 'Failed') return out('failed', 'Failed', err || 'The message could not be sent.');
if (st === 'Unconfirmed') return out('unconfirmed', 'Unconfirmed', err || 'It could not be confirmed whether the message went out. Check the chat in WhatsApp before sending again.');
if (st === 'Sending') {
  if (waited > 180) return out('unconfirmed', 'Unconfirmed', 'The send did not finish, so it is not known whether the message went out. Check the chat in WhatsApp before sending again.');
  return out('running', 'Sending', 'Sending...');
}
if (st === 'Pending') {
  let msg = 'Waiting for WhatsApp to confirm...';
  if (waited > 90) msg = 'Still waiting for WhatsApp to confirm. If this stays pending, check that the WAHA webhook for message.ack points to this workflow.';
  return out('running', 'Pending', msg);
}
return out('none', 'Not sent', 'No WhatsApp message has been sent to this lead yet.');

const raw = $input.first().json || {};
const b = raw.body || raw;
const skip = (why) => [{ json: { relevant: false, reason: why } }];
if (String(b.event || '') !== 'message.ack') return skip('not a message.ack event');
const pl = b.payload || {};
if (pl.fromMe === false) return skip('ack for a received message');
const full = (typeof pl.id === 'string') ? pl.id : String((pl.id && pl.id._serialized) || '');
const shortId = full.split('_').filter(x => /^[A-Za-z0-9]{10,64}$/.test(x)).pop() || '';
if (!shortId) return skip('no message id');
const names = { ERROR: -1, PENDING: 0, SERVER: 1, DEVICE: 2, READ: 3, PLAYED: 4 };
const ack = (typeof pl.ack === 'number') ? pl.ack : names[String(pl.ackName || '').toUpperCase()];
if (typeof ack !== 'number') return skip('no ack value');
const map = { '-1': 'Failed', '0': 'Pending', '1': 'Sent', '2': 'Delivered', '3': 'Read', '4': 'Played' };
const status = map[String(ack)];
if (!status) return skip('unknown ack value');
return [{ json: { relevant: true, short_id: shortId, full_id: full, ack: ack, status: status, error: ack === -1 ? 'WhatsApp reported a delivery error (ack -1).' : '' } }];

const a = $('Parse WAHA Ack').first().json;
const rows = $input.all().map(i => i.json || {}).filter(r => r && !r.error && r.Lead_ID && String(r.Run_ID || '') === a.short_id);
if (!rows.length) return [{ json: { update: false, reason: 'message id not found in the sheet' } }];
const row = rows[0];
const rank = { Pending: 0, Sent: 1, Delivered: 2, Read: 3, Played: 4 };
const cur = (row.Status in rank) ? rank[row.Status] : -1;
if (a.ack === -1) { if (cur >= 2) return [{ json: { update: false, reason: 'already delivered' } }]; }
else if (a.ack <= cur) return [{ json: { update: false, reason: 'older or same status' } }];
return [{ json: { update: true, lead_id: String(row.Lead_ID), business_name: String(row.Business_Name || ''), number: String(row.WhatsApp_Number || '').replace(/\D/g, ''), status: a.status, error: a.error } }];
